        {
          "name": "initRevision",
          "access": "internal",
          "description": "<p>This method sets revision number of the initial data set. It should be called once after loading the data to set\na starting point to sync revisions with the backend.</p>",
          "scope": "instance",
          "parameters": [
            {
              "name": "revision",
              "type": "String"
            },
            {
              "name": "enableAutoRecord",
              "type": "Boolean",
              "default": true,
              "optional": true
            }
          ]
        },
        {
          "name": "trackRecords",
          "access": "private",
          "description": "<p>This method keeps a map of every record referenced by the StateTrackingManager. Record is already\nreferenced in the Action inside the Transaction inside the STM queue, unaccessible from the outside.\nUsing this map we can track id/phantom id changes which is required in some cases</p>",
          "scope": "instance",
          "parameters": [
            {
              "name": "stores",
              "type": "Array.<Core.data.Store>",
              "description": "<p>Stores to/from which records are added/removed</p>"
            },
            {
              "name": "models",
              "type": "Array.<Core.data.Model>",
              "description": "<p>Added/removed records</p>"
            }
          ]
        },
        {
          "name": "increaseRevision",
          "access": "internal",
          "description": "<p>This method takes transaction and creates local revision</p>",
          "scope": "instance",
          "parameters": [
            {
              "name": "transaction",
              "type": "Core.data.stm.RevisionTransaction"
            },
            {
              "name": "changes",
              "type": "Object",
              "description": "<p>Can be provided to a conflict resolving revision</p>",
              "optional": true
            }
          ]
        },
        {
          "name": "createDataCorrectionTransaction",
          "access": "internal",
          "description": "<p>This method creates special data revision which has no input state, only a data correction for a case when\napplying remote revisions lead to new changes. This revision will be sent, it should be persisted on the backend,\nand any client applying it should not see any changes after.</p>",
          "scope": "instance"
        },
        {
          "name": "createConflictResolutionRevision",
          "access": "internal",
          "description": "<p>This method creates special conflict resolution revision which contains only conflict resolution actions. It is\nlinked to the revision with a conflict via <code>conflictResolutionFor</code> property. Such revision cannot be rolled back\nlocally because it will introduce the same conflict again.</p>",
          "scope": "instance"
        },
        {
          "name": "commitRevision",
          "access": "internal",
          "description": "<p>Commits revision, can assign a new id for the local revision which is already applied, but was\nfinally committed on the backend.</p>",
          "scope": "instance",
          "parameters": [
            {
              "name": "oldId",
              "type": "String"
            },
            {
              "name": "newId",
              "type": "String/Number",
              "optional": true
            }
          ]
        },
        {
          "name": "cleanUpRevisions",
          "access": "internal",
          "description": "<p>Clears committed revisions, we only need to use last one.</p>",
          "scope": "instance"
        },
        {
          "name": "markCurrentTransactionContentUserInput",
          "access": "internal",
          "description": "<p>Used to distinguish user input from values calculated by the project. If any actions in the revision are marked\nas user input then checkout logic will only use user input. If nothing is marked, then revision is not treated\nspecially.</p>",
          "scope": "instance"
        }
