            {
              "name": "axes.x",
              "type": "Boolean",
              "description": "<p>Sync horizontal scroll.</p>",
              "isSubParam": true
            },
            {
              "name": "axes.y",
              "type": "Boolean",
              "description": "<p>Sync vertical scroll.</p>",
              "isSubParam": true
            }
