          "name": "isGridEditBase",
          "description": "Identifies an object as an instance of <a href=\"#Grid/feature/base/GridEditBase\">GridEditBase</a> class, or subclass thereof.",
          "defaultValue": true,
          "readonly": true,
          "category": "Class hierarchy",
          "advanced": true,
