        {
          "name": "applyStartEndParameters",
          "access": "private",
          "description": "<p>Applies the start and end date to each event store request (formatted in the same way as the start date field,\ndefined in the EventStore Model class).</p>",
          "scope": "instance",
          "category": "Data"
        },
        {
          "name": "highlightEvents",
          "description": "<p>Highlights the elements of the passed event or assignment records (or record ids). If <code>scrollToClosest</code> is set to\n<code>true</code> (which it is by default), the highlighted event element closest to the viewport center will be scrolled\ninto view.</p>\n<p>The highlighting will be done by adding the css class <code>b-highlighted</code> to the highlighted event elements. Also,\nthe css class <code>b-is-highlighting</code> will be added to the <code>TimeAxisSubGrid</code> element.</p>\n<pre class=\"prettyprint source lang-javascript\"><code>// Highlight single event\nscheduler.highlightEvents({ events : 22 });\n// Highlight multiple events\nscheduler.highlightEvents({ events : [1, 40] });\n// Don't scroll to highlighted event, and don't un-highlight on click\nscheduler.highlightEvents({ events : 1000, scroll : false, unhighlightOnClick : false });\n</code></pre>",
          "scope": "instance",
          "category": "Misc",
          "parameters": [
            {
              "name": "options",
              "type": "Object",
              "description": "<p>Options config object</p>"
            },
            {
              "name": "options.events",
              "type": [
                "Scheduler.model.EventModel",
                "Scheduler.model.AssignmentModel",
                "Number",
                "String",
                "Array.<Scheduler.model.EventModel>",
                "Array.<Scheduler.model.AssignmentModel>",
                "Array.<Number>",
                "Array.<String>"
              ],
              "description": "<p>The event records, assignment records or record ids to highlight. If providing ids, they will be interpreted as\nevent ids only if <a href=\"#Scheduler/data/EventStore#config-singleAssignment\">singleAssignment</a> is <code>true</code>, otherwise they will be\ninterpreted as assignment ids. If an empty array is passed, the <code>b-is-highlighting</code> class will be applied,\nrendering all event elements in the style of <code>:not(.b-highlighted)</code>.</p>",
              "isSubParam": true
            },
            {
              "name": "options.scroll",
              "type": [
                "Boolean",
                "Core.helper.util.Scroller#BryntumScrollOptions"
              ],
              "description": "<p>If <code>false</code>, no scrolling will be performed. If a\nscrollOptions object, this object will be passed to the scroll function providing details on how to scroll.</p>",
              "optional": true,
              "isSubParam": true
            },
            {
              "name": "options.unhighlightOnClick",
              "type": "Boolean",
              "description": "<p>If <code>false</code>, a call to <a href=\"#Scheduler/view/TimelineBase#function-unhighlightEvents\">unhighlightEvents</a> is needed\nto remove the highlighting. Otherwise, the highlighting will be removed when the user clicks somewhere in the\nbrowser window.</p>",
              "optional": true,
              "isSubParam": true
            },
            {
              "name": "options.unhighlightOthers",
              "type": "Boolean",
              "description": "<p>If <code>true</code> this will automatically un-highlight the events not\npresent in the <code>events</code> property</p>",
              "optional": true,
              "isSubParam": true
            }
          ]
        },
        {
          "name": "flashHighlightedAssignment",
          "access": "private",
          "description": "<p>Flashes the rendered element for a single highlighted assignment/task.</p>",
          "scope": "instance"
        },
        {
          "name": "unhighlightEvents",
          "description": "<p>Removes highlighting from the elements of the passed event or assignment records (or record ids). If no events\nare passed all highlighted events will be un-highlighted.</p>\n<pre class=\"prettyprint source lang-javascript\"><code>scheduler.unhighlightEvents({ events : 22 }); // single event\nscheduler.unhighlightEvents({ events : [1, 40] }); // multiple events\n</code></pre>",
          "scope": "instance",
          "category": "Misc",
          "parameters": [
            {
              "name": "options",
              "type": "Object",
              "description": "<p>Options config object</p>",
              "optional": true
            },
            {
              "name": "options.events",
              "type": [
                "Scheduler.model.EventModel",
                "Scheduler.model.AssignmentModel",
                "Number",
                "String",
                "Array.<Scheduler.model.EventModel>",
                "Array.<Scheduler.model.AssignmentModel>",
                "Array.<Number>",
                "Array.<String>"
              ],
              "description": "<p>The event or assignment records or record ids to un-highlight. Omit this to un-highlight all.</p>",
              "optional": true,
              "isSubParam": true
            }
          ]
        }
