      "name": "DataSeriesRole",
      "type": "Chart.widget.Chart#DataSeriesRole",
      "properties": [
        {
          "type": {
            "names": [
              "'x'",
              "'y'",
              "'size'"
            ]
          },
          "description": "<p>The axis along which values in this series will be plotted. <code>size</code> is applicable\nonly to the <code>bubble</code> chart type.</p>",
          "name": "axis"
        },
        {
          "type": {
            "names": [
              "Number"
            ]
          },
          "description": "<p>When multiple data points are combined into a single series (for example <code>x</code>, <code>y</code>,\nand <code>size</code> roles), this property indicates the series to which this role belongs.</p>",
          "name": "seriesIndex"
        }
      ],
